import unittest

from app.db import TransientConnectionError, execute
from app.writer import record_batch


class Connection:
    def __init__(self, result=None, error=None):
        self.result = result
        self.error = error
        self.operations = []

    def run(self, op):
        self.operations.append(op)
        if self.error is not None:
            raise self.error
        return self.result


class Connector:
    def __init__(self, connections):
        self.connections = iter(connections)
        self.dsns = []

    def __call__(self, dsn):
        self.dsns.append(dsn)
        return next(self.connections)


class ExecuteTests(unittest.TestCase):
    def setUp(self):
        self.primary = "postgresql://primary/usage"
        self.settings = {
            "db": {
                "primary": self.primary,
                "replica": "postgresql://replica/usage",
                "reconnect_attempts": 3,
                "backoff_ms": 0,
            }
        }
        self.op = {"id": "usage-1"}

    def test_reconnects_and_reissues_after_transient_connection_error(self):
        dropped = Connection(error=TransientConnectionError("connection dropped"))
        recovered = Connection(result=42)
        connect = Connector([dropped, recovered])

        self.assertEqual(execute(self.op, connect, self.settings), 42)
        self.assertEqual(connect.dsns, [self.primary, self.primary])
        self.assertEqual(dropped.operations, [self.op])
        self.assertEqual(recovered.operations, [self.op])

    def test_raises_last_transient_error_after_attempt_budget_is_exhausted(self):
        errors = [TransientConnectionError(str(attempt)) for attempt in range(3)]
        connections = [Connection(error=error) for error in errors]
        connect = Connector(connections)

        with self.assertRaises(TransientConnectionError) as raised:
            execute(self.op, connect, self.settings)

        self.assertIs(raised.exception, errors[-1])
        self.assertEqual(connect.dsns, [self.primary] * 3)
        self.assertEqual([connection.operations for connection in connections], [[self.op]] * 3)

    def test_does_not_retry_other_exceptions(self):
        failure = ValueError("invalid operation")
        failed = Connection(error=failure)
        [REDACTED] = Connection(result=42)
        connect = Connector([failed, [REDACTED]])

        with self.assertRaises(ValueError) as raised:
            execute(self.op, connect, self.settings)

        self.assertIs(raised.exception, failure)
        self.assertEqual(connect.dsns, [self.primary])
        self.assertEqual([REDACTED].operations, [])

    def test_record_batch_marks_exhausted_operation_failed(self):
        self.settings["db"]["reconnect_attempts"] = 2
        connect = Connector(
            [
                Connection(error=TransientConnectionError("first drop")),
                Connection(error=TransientConnectionError("second drop")),
            ]
        )

        self.assertEqual(
            record_batch([self.op], connect, self.settings),
            [{"id": "usage-1", "outcome": "failed", "error": "TransientConnectionError"}],
        )


if __name__ == "__main__":
    unittest.main()

